def group_signups(entries):
    groups = {}
    for name, activity in entries:
        if activity not in groups:
            groups[activity] = []
        groups[activity].append(name)
    return groups

def claim_items(shared_list, items_to_claim):
    remaining = list(shared_list)
    for item in items_to_claim:
        if item in remaining:
            remaining.remove(item)
    return [remaining, shared_list]

def find_crate(codes, target):
    for i in range(len(codes)):
        if codes[i] == target:
            return i
    return -1

def first_alarm(readings, threshold):
    for i in range(len(readings)):
        if readings[i] > threshold:
            return i + 1
    return -1

def rank_by_time(bibs, times):
    bibs = list(bibs)
    times = list(times)
    n = len(times)
    for i in range(n):
        for j in range(0, n - i - 1):
            if times[j] > times[j + 1]:
                times[j], times[j + 1] = times[j + 1], times[j]
                bibs[j], bibs[j + 1] = bibs[j + 1], bibs[j]
    return bibs

def trim_silence(levels):
    start = 0
    end = len(levels) - 1
    while start <= end and levels[start] == 0:
        start += 1
    while end >= start and levels[end] == 0:
        end -= 1
    return levels[start:end + 1]

def lower_bound(prices, target):
    lo, hi = 0, len(prices)
    while lo < hi:
        mid = (lo + hi) // 2
        if prices[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo

def leaderboard(players):
    ranked = sorted(players, key=lambda p: (-p["score"], p["attempts"], p["name"]))
    return [p["name"] for p in ranked]

def trip_summary(stops):
    def stop_cost(stop):
        liters, price = stop
        cost = round(liters * price, 2)
        is_premium = price > 1.50
        return (cost, is_premium)
    total_cost = 0.0
    premium_count = 0
    for stop in stops:
        cost, is_premium = stop_cost(stop)
        total_cost += cost
        if is_premium:
            premium_count += 1
    return (round(total_cost, 2), premium_count)

def rainfall_summary(readings):
    if not readings:
        return (0, None)
    total = 0.0
    wettest_day = readings[0][0]
    wettest_amount = readings[0][1]
    for day, mm in readings:
        total += mm
        if mm > wettest_amount:
            wettest_amount = mm
            wettest_day = day
    return (round(total, 1), wettest_day)

def needs_restock(inventory):
    result = []
    for item_name, quantity, reorder_level in inventory:
        if quantity < reorder_level:
            result.append(item_name)
    return result

def pick_next_game(games, votes):
    counts = {g: 0 for g in games}
    for v in votes:
        if v in counts:
            counts[v] += 1
    best_game = games[0]
    best_count = counts[games[0]]
    for g in games:
        if counts[g] > best_count:
            best_count = counts[g]
            best_game = g
    return (best_game, best_count)

def clean_attendance_row(fields):
    name = fields[0].strip()
    if name == "":
        return None
    status = fields[1].strip()
    if status == "":
        status = "present"
    raw_late = fields[2].strip()
    try:
        minutes_late = int(raw_late)
    except ValueError:
        minutes_late = 0
    if minutes_late < 0:
        minutes_late = 0
    return [name, status, minutes_late]

def total_revenue_by_drink(records):
    totals = {}
    for rec in records:
        price_str = rec["price"].strip()
        if price_str == "":
            continue
        drink = rec["drink"]
        totals[drink] = totals.get(drink, 0.0) + float(price_str)
    result = [[drink, round(total, 2)] for drink, total in totals.items()]
    result.sort(key=lambda pair: pair[0])
    return result

import csv
import io

def average_temperature(csv_text):
    reader = csv.DictReader(io.StringIO(csv_text))
    total = 0.0
    count = 0
    for row in reader:
        raw = row["temperature"].strip()
        if raw == "" or raw.upper() == "NA":
            continue
        total += float(raw)
        count += 1
    if count == 0:
        return None
    return round(total / count, 1)
